# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">MASALDAN FİLM ŞERİDİNE (STORYBOARD) DÖNÜŞTÜRME SÜRECİ</text>\n  <rect x="22" y="40" width="320" height="178" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="182" y="62" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1e40af">MASALIN YAPI UNSURLARI VE BÖLÜMLERİ</text>\n  <text x="34" y="85" font-size="11.2" fill="#1e3a8a">• 1. Döşeme: Tekerleme ile masal atmosferine giriş.</text>\n  <text x="34" y="110" font-size="11.2" fill="#1e3a8a">• 2. Serim: Kahramanların, mekânın ve durumun tanıtımı.</text>\n  <text x="34" y="135" font-size="11.2" fill="#1e3a8a">• 3. Düğüm: Çatışma, yolculuk, olağanüstü sınav ve merak.</text>\n  <text x="34" y="160" font-size="11.2" fill="#1e3a8a">• 4. Çözüm: İyiliğin galip gelmesi ve sorunun çözülmesi.</text>\n  <text x="34" y="185" font-size="11.2" fill="#1e3a8a">• 5. Dilek: \'Gökten üç elma düştü...\' iyi dilek kalıbı.</text>\n  <rect x="358" y="40" width="320" height="178" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="518" y="62" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#92400e">BİR FİLM ŞERİDİ KARESİNİN 4 BİLEŞENİ</text>\n  <text x="370" y="85" font-size="11.2" fill="#78350f">• 1. Görsel Kare: Sahnenin, dekorun ve karakterin çizimi.</text>\n  <text x="370" y="110" font-size="11.2" fill="#78350f">• 2. Kamera / Plan: Genel çekim, orta çekim, yakın (yüz) çekim.</text>\n  <text x="370" y="135" font-size="11.2" fill="#78350f">• 3. Metin / Söz: Dış ses (anlatıcı) ve karakter diyalogları.</text>\n  <text x="370" y="160" font-size="11.2" fill="#78350f">• 4. İşitsel Öge: Sahne duygusuna uygun müzik ve ses efekti.</text>\n  <text x="370" y="185" font-size="11.2" fill="#78350f">• Amaç: Sözlü anlatıyı görsel-işitsel çok modlu metne çevirmek.</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">Masalın başındaki mekan tanıtımında \'Genel Çekim\', kahramanın duygusunu yansıtırken ise \'Yakın Çekim\' tercih edilir.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">YAZMA SÜRECİNDE ANLATIM, SÖZ VARLIĞI VE DİL BİLİNCİ</text>\n  <rect x="22" y="40" width="320" height="178" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="182" y="62" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#166534">ANLATIM BİÇİMLERİ VE SÖZ VARLIĞI</text>\n  <text x="34" y="85" font-size="11.2" fill="#14532d">• Betimleyici Anlatım: Mekân, kostüm ve ışık tasvirleri.</text>\n  <text x="34" y="110" font-size="11.2" fill="#14532d">• Öyküleyici Anlatım: Kareler arasındaki olay ve eylem akışı.</text>\n  <text x="34" y="135" font-size="11.2" fill="#14532d">• Söz Varlığı: Deyimler, atasözleri, tekerlemeler, kalıp sözler.</text>\n  <text x="34" y="160" font-size="11.2" fill="#14532d">• Açık ve Örtük İleti: İyilik, doğruluk ve merhamet mesajları.</text>\n  <text x="34" y="185" font-size="11.2" fill="#14532d">• Özgün Üslup: Hedef kitleye uygun akıcı ve etkileyici dil.</text>\n  <rect x="358" y="40" width="320" height="178" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="518" y="62" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1e40af">TÜRKÇEYİ ÖZENLİ KULLANMA (TERİM KARŞILIKLARI)</text>\n  <text x="370" y="85" font-size="11.2" fill="#1e3a8a">• Storyboard -&gt; Film şeridi / Resimli taslak</text>\n  <text x="370" y="110" font-size="11.2" fill="#1e3a8a">• Flashback -&gt; Geriye dönüş | Sekans -&gt; Sahne dizisi</text>\n  <text x="370" y="135" font-size="11.2" fill="#1e3a8a">• Voice-over -&gt; Dış ses / Anlatıcı sesi</text>\n  <text x="370" y="160" font-size="11.2" fill="#1e3a8a">• Close-up -&gt; Yakın çekim | Perspektif -&gt; Bakış açısı</text>\n  <text x="370" y="185" font-size="11.2" fill="#1e3a8a">• İlke: Yabancı sözcükler yerine Türkçe karşılıkları kullanılır.</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">Film şeridi metinlerinde sahne açıklamaları genellikle geniş zaman (-r) veya şimdiki zaman (-yor) kipiyle yazılır.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">BAĞDAŞIKLIK, YAZIM VE NOKTALAMA KURALLARI UYGULAMASI</text>\n  <rect x="22" y="40" width="320" height="178" rx="10" fill="#faf5ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="182" y="62" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#6b21a8">BAĞDAŞIKLIK VE BAĞLAŞIKLIK İLKELERİ</text>\n  <text x="34" y="85" font-size="11.2" fill="#581c87">• Bağlaşıklık: Olay akışındaki mantıksal ve anlamsal tutarlılık.</text>\n  <text x="34" y="110" font-size="11.2" fill="#581c87">• Bağdaşıklık: Cümleler arası dil bilgisel bağlantı araçları.</text>\n  <text x="34" y="135" font-size="11.2" fill="#581c87">• Geçiş İfadeleri: \'Bu sırada, ardından, bunun üzerine, derken\'.</text>\n  <text x="34" y="160" font-size="11.2" fill="#581c87">• Gönderim: İsimlerin yerine uygun kişi/işaret zamiri kullanma.</text>\n  <text x="34" y="185" font-size="11.2" fill="#581c87">• Bütünlük: Giriş, gelişme ve sonuç karelerinin organik uyumu.</text>\n  <rect x="358" y="40" width="320" height="178" rx="10" fill="#fff7ed" stroke="#ea580c" stroke-width="2"/>\n  <text x="518" y="62" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#9a3412">SENARYO VE FİLM ŞERİDİNDE NOKTALAMA / YAZIM</text>\n  <text x="370" y="85" font-size="11.2" fill="#7c2d12">• Konuşma Çizgisi (—): Diyalog satırlarının başında kullanılır.</text>\n  <text x="370" y="110" font-size="11.2" fill="#7c2d12">• Yay Ayraç ( ): Jest, mimik, tonlama ve sahne hareketi için.</text>\n  <text x="370" y="135" font-size="11.2" fill="#7c2d12">• • Örnek: BİLGE DEDE — (Asasına dayanıp gülümseyerek)...</text>\n  <text x="370" y="160" font-size="11.2" fill="#7c2d12">• Üç Nokta (...): Heyecandan yarım kalan söz ve sessizlikler.</text>\n  <text x="370" y="185" font-size="11.2" fill="#7c2d12">• Yazım: Birleşik fiiller (yardım etmek vs. affetmek/hissetmek).</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">Yay ayraç içindeki sahne yönergeleri büyük harfle başlar ve sonuna nokta konulmaz (veya cümle ise nokta konur).</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get('bolumler', [])):
        if i < len(SVGS):
            b['gorsel'] = SVGS[i]
